import { createHash } from "node:crypto";

// Every session has two identifiers:
// - a secret *key*, generated by the browser tab and never shown to anyone
//   else. It is the session's credential: every API call presents it.
// - a public *id*, derived from the key with a one-way hash. This is what
//   other people see (on dots, in signals). Knowing it doesn't let anyone act
//   as that session, because the key can't be recovered from it.
//
// Previously one client-generated id was both: /api/poll handed every peer's
// id to everyone, and every endpoint trusted whatever id the caller sent, so
// anyone could read someone's mailbox, answer their requests, move their dot
// or kick them off the map.
//
// The id is derived rather than issued, so the server stays stateless (no
// secret to configure, no extra table).

const KEY_RE = /^[A-Za-z0-9_-]{32,128}$/;
const PUBLIC_ID_RE = /^[A-Za-z0-9_-]{22}$/;

export type Session = { key: string; id: string };

export function isSessionKey(value: unknown): value is string {
  return typeof value === "string" && KEY_RE.test(value);
}

export function isPublicId(value: unknown): value is string {
  return typeof value === "string" && PUBLIC_ID_RE.test(value);
}

function digest(purpose: string, key: string): Buffer {
  return createHash("sha256").update(`pulse:${purpose}:${key}`).digest();
}

// 132 bits of the hash, base64url.
export function publicIdFor(key: string): string {
  return digest("id", key).toString("base64url").slice(0, 22);
}

// Two numbers in [0, 1) that are fixed for the whole session. The privacy
// offset is built from these instead of Math.random(), so re-joining (the
// client re-joins whenever its row is reaped) puts the dot back in the same
// place. A fresh random offset on every join gave anyone watching a new sample
// each time, and averaging enough samples converges on the real location.
export function offsetSeed(key: string): [number, number] {
  const h = digest("offset", key);
  return [h.readUInt32BE(0) / 2 ** 32, h.readUInt32BE(4) / 2 ** 32];
}

// The key travels in the Authorization header, not the URL, so it doesn't end
// up in access logs or browser history.
export function getSession(request: Request): Session | null {
  const auth = request.headers.get("authorization");
  const key = auth?.startsWith("Bearer ") ? auth.slice(7) : null;
  return isSessionKey(key) ? { key, id: publicIdFor(key) } : null;
}

export function unauthorized(): Response {
  return Response.json({ error: "missing or invalid session key" }, { status: 401 });
}
